"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["28029"],{61168(e,t,a){a.r(t),a.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>o,contentTitle:()=>c,toc:()=>d,assets:()=>l});var i=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-validate","title":"Validate ABHA policy link (v2)","description":"Second half of the two-step v2 link: confirms an initiated ABHA policy link with the passcode and transactionId query parameters.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-validate.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-validate","permalink":"/docs/pr-45/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-validate","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Validate ABHA policy link (v2)","sidebar_label":"Validate ABHA policy link (v2)","sidebar_class_name":"api-method api-method--get","description":"Second half of the two-step v2 link: confirms an initiated ABHA policy link with the passcode and transactionId query parameters.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Initiate ABHA policy link (v2)","permalink":"/docs/pr-45/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-init"},"next":{"title":"Submit the de-link ABHA policies","permalink":"/docs/pr-45/docs/nhcx/v1/api/registry/endpoints/registry-participant-delink-abha-policy"}}'),n=a(62540),r=a(43023),s=a(85030),p=JSON.parse('{"id":"registry_v2_participant_link_abha_policy_validate","module":"Participant registry","moduleId":"registry","kind":"operation","method":"GET","path":"/v2/participant/link/abha/policy/validate","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Validate ABHA policy link (v2)","title":"Validate ABHA policy link (v2)","description":"Second half of the two-step v2 link: confirms an initiated ABHA policy link with the passcode and transactionId query parameters.\\n\\n### Business purpose\\n\\nThis GET endpoint closes the approval loop opened by /v2/participant/link/abha/policy/init. By requiring a passcode tied to a transactionId, it ensures that a member-layer write attributed to a payer or TPA was actually authorised by that organisation, in the same way that participant creation and update are confirmed through /validate and /update/validate. The value to the ecosystem is trust in the registry: providers rely on the policy lookup, so the links behind it should be deliberate and traceable.\\n\\n### When to use\\n\\nCall it after the init call, once you have the passcode. It confirms the link.\\n\\n### Preconditions\\n\\n- An init call has returned a transaction ID.\\n- You have the passcode for that transaction.\\n- You have a valid access token in the `bearer_auth` header.\\n\\n### Postconditions\\n\\nThe link is confirmed and providers can find the member\'s policies. If the passcode or transaction is wrong, start again with init.\\n\\n### Common mistakes\\n\\n- Sending `passcode` and `transactionId` in a body. They go in the query string.\\n- Using a transaction ID from a different call.\\n- Waiting until the passcode expires.\\n\\n### Best practices\\n\\n- URL-encode both query parameters and log the transactionId with the outcome.\\n- Treat a 404 or an errormessage as a signal to restart from init rather than retrying the same passcode indefinitely.\\n- Verify the confirmed link with /participant/get/policies using the same ABHA number.\\n- Keep the init and validate calls under the same participant token so the identity check passes.\\n\\n### Related scenario\\n\\nA TPA\'s operations desk initiated a policy link for a new member earlier in the day through /v2/participant/link/abha/policy/init and stored the transaction identifier against the case. When the authorised approver supplies the passcode, the system calls GET /v2/participant/link/abha/policy/validate?passcode=...&transactionId=... and receives a 200 with a result string. The desk then runs /v2/participant/get/policies for the member\'s ABHA number, sees the product listed, and closes the linking task; the next call in the member\'s journey will be the hospital\'s coverage-eligibility check.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","gateway":"nhcx","security":[{"name":"bearerAuth","type":"apiKey","in":"header","headerName":"bearer_auth","description":"Every NHCX call carries the access token from the session call in a header named `bearer_auth`, as the word `Bearer`, a space and the token. NHCX reads `bearer_auth`, not `Authorization`.","example":"Bearer <access token>","prefix":"Bearer "}],"headers":[{"name":"Accept","required":true,"description":"Always `application/json` on the participant service.","example":"application/json","type":"string"}],"pathParams":[],"queryParams":[],"body":[],"responses":[{"status":"200","description":"On success the endpoint returns HTTP 200 with ParticipantLinkAbhaResponse (optional result and errormessage).","example":{"result":"success"},"synthesised":false,"fields":[{"name":"result","type":"string","required":false,"description":""}]}],"curl":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.get(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate\\",\\n    headers={\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Accept\\": \\"application/json\\",\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate\\", {\\n  method: \\"GET\\",\\n  headers: {\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Accept\\": \\"application/json\\",\\n  },\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate\\"))\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Accept\\", \\"application/json\\")\\n    .method(\\"GET\\", HttpRequest.BodyPublishers.noBody())\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'GET\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Accept: application/json\',\\n    ],\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n)\\n\\nfunc main() {\\n\\treq, err := http.NewRequest(\\"GET\\", \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate\\", nil)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Accept\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"GET\\"), \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"Accept\\", \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate\')\\nrequest = Net::HTTP::Get.new(uri)\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Accept\'] = \'application/json\'\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let o={title:"Validate ABHA policy link (v2)",sidebar_label:"Validate ABHA policy link (v2)",sidebar_class_name:"api-method api-method--get",description:"Second half of the two-step v2 link: confirms an initiated ABHA policy link with the passcode and transactionId query parameters.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},c,l={},d=[];function h(e){return(0,n.jsx)(s.A,{operation:p})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(h,{...e})}):h(e)}}}]);